import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './AuthForm.css';
import api, { setToken } from '../api';

const LoginPage = ({
  initialEmail = '',
  initialPassword = '',
  onLoginSuccess,
  onNavigateToRegister
}) => {
  const [email, setEmail] = useState(initialEmail);
  const [password, setPassword] = useState(initialPassword);
  const [errors, setErrors] = useState({});
  const [authError, setAuthError] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const navigate = useNavigate();

  useEffect(() => {
    if (initialEmail) setEmail(initialEmail);
    if (initialPassword) setPassword(initialPassword);
  }, [initialEmail, initialPassword]);

  const validateForm = () => {
    const errs = {};
    if (!email.trim()) errs.email = 'Email address or username is required.';
    if (!password) errs.password = 'Password is required.';
    setErrors(errs);
    return Object.keys(errs).length === 0;
  };

  // Helper function to dispatch successful login state
  const dispatchLoginSuccess = (token, user) => {
    setToken(token);
    if (onLoginSuccess) {
      onLoginSuccess(user);
    } else {
      navigate(user.role === 'admin' ? '/admin' : '/student');
    }
  };

  // TEMPORARY: One-click bypass button handler
  const handleQuickAdminLogin = () => {
    const mockAdminUser = {
      id: 999,
      email: 'admin@system.com',
      full_name: 'Temp Admin',
      role: 'admin'
    };
    dispatchLoginSuccess('temp-mock-admin-token-12345', mockAdminUser);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setAuthError('');

    if (!validateForm()) return;

    const trimmedEmail = email.trim().toLowerCase();

    // TEMPORARY: Form field bypass when inputting 'admin'
    if (trimmedEmail === 'admin') {
      const mockAdminUser = {
        id: 999,
        email: 'admin@system.com',
        full_name: 'Temp Admin',
        role: 'admin'
      };
      dispatchLoginSuccess('temp-mock-admin-token-12345', mockAdminUser);
      return;
    }

    setSubmitting(true);
    try {
      const { access_token, user } = await api.login({
        email: trimmedEmail,
        password
      });

      dispatchLoginSuccess(access_token, user);
    } catch (err) {
      setAuthError(err.message || 'Incorrect email or password');
    } finally {
      setSubmitting(false);
    }
  };

  const handleRegisterNavigation = () => {
    if (onNavigateToRegister) {
      onNavigateToRegister();
    } else {
      navigate('/register');
    }
  };

  return (
    <div className="auth-card-container">
      <div className="auth-card">
        <h2>Portal Login</h2>
        <p className="auth-subtitle">Sign in with your registered account details.</p>

        {/* TEMPORARY: Dev Quick Access Banner */}
        <div style={{
          backgroundColor: '#fef3c7',
          border: '1px solid #f59e0b',
          borderRadius: '6px',
          padding: '0.75rem',
          marginBottom: '1rem',
          textAlign: 'center'
        }}>
          <p style={{ margin: '0 0 0.5rem 0', fontSize: '0.875rem', color: '#92400e', fontWeight: 600 }}>
            ⚡ Dev Mode Active
          </p>
          <button 
            type="button" 
            onClick={handleQuickAdminLogin}
            style={{
              backgroundColor: '#d97706',
              color: '#fff',
              border: 'none',
              padding: '0.4rem 0.8rem',
              borderRadius: '4px',
              cursor: 'pointer',
              fontWeight: 600,
              fontSize: '0.8rem'
            }}
          >
            Bypass & Enter Admin Panel
          </button>
        </div>

        {authError && <div className="error-banner">{authError}</div>}

        <form onSubmit={handleSubmit} noValidate>
          <div className="form-group">
            <label htmlFor="login-email">Email / Username</label>
            <input
              id="login-email"
              type="text"
              className={errors.email ? 'input-error' : ''}
              placeholder="Type 'admin' for temp access"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
            {errors.email && <span className="field-error">{errors.email}</span>}
          </div>

          <div className="form-group">
            <label htmlFor="login-password">Password</label>
            <input
              id="login-password"
              type="password"
              className={errors.password ? 'input-error' : ''}
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            {errors.password && <span className="field-error">{errors.password}</span>}
          </div>

          <button type="submit" className="auth-btn" disabled={submitting}>
            {submitting ? 'Signing in…' : 'Log In'}
          </button>
        </form>

        <p className="auth-footer">
          Don't have an account?{' '}
          <button type="button" className="link-btn" onClick={handleRegisterNavigation}>
            Register here
          </button>
        </p>
      </div>
    </div>
  );
};

export default LoginPage;
